// === Tab: mySketch ===
// "From Chaos to Earth" submission for the #WCCChallenge theme: "earth" 7 sept 2025
//
// Minimalist simulation of the aggregation of planet Earth
//
// First I prepare a spherical configuration, then I simulate a chaotic situation 
// from which I gradually return to the original sphere
//

let poi = [];
let v = 0; // variable to gradually show the earth's axis

function setup() {
	createCanvas(500, 500, WEBGL);
	pixelDensity(1)
	//
	// builds each of the 200 elements of this multicolored "earth" and places 
	// them on the surface of the schematic sphere
	//
	let ra = 200
	for (let k = 0; k < 10; k++) {
		let ang1 = map(k, 0, 10 - 1, -HALF_PI, HALF_PI);
		let cosAng = Math.cos(ang1);
		let sinAng = Math.sin(ang1);

		for (let j = 0; j < 20; j++) {
			let ang2 = map(j, 0, 20, 0, TWO_PI);
			let xx = ra * cosAng * Math.cos(ang2);
			let yy = ra * sinAng;
			let zz = ra * cosAng * Math.sin(ang2);
			let r = int(random(256))
			let g = int(random(256));
			let b = int(random(256));
			clor = "#" + hex(r, 2) + hex(g, 2) + hex(b, 2);
			let coo = {
				x: xx,
				y: yy,
				z: zz,
				dx: random(-10, 10),
				dy: random(-10, 10),
				dz: 0,
				cycles: random(10, 280),
				cl: clor
			};
			poi.push(coo);
		}
	}
	//
	// randomly undoes the sphere and each element memorizes the parameters
	// of its displacement
	//
	poi.forEach((f) => {
		for (k = 0; k < f.cycles - 1; k++) {
			f.x += f.dx;
			f.y += f.dy;
			f.z += f.dz;
		}
	});
	angleMode(DEGREES)
}

function draw() {
	push()
	rotateZ(23.5)
	rotateY(frameCount / 4)
	background(0);
	let axisShow = true
	//
	// recomposes the Earth by reversing the displacement of each single element
	//
	poi.forEach((f) => {
		if (frameCount < f.cycles) {
			f.x -= f.dx;
			f.y -= f.dy;
			f.z -= f.dz;
			axisShow = false
			v = frameCount
		}
		stroke(f.cl)
		strokeWeight(4)
		point(f.x, f.y, f.z);
	});
	//
	// Each element is positioned correctly at randomly different times.
	// When all the elements are in the correct position, the Earth's axis
	// gradually appears.
	//
	if (axisShow == true) {
		let clor;
		if ((20 + frameCount - v) < 256) {
			clor = "#0000ff" + hex((20 + frameCount - v), 2); // + 20 for graphic reasons only
		} else {
			clor = "#0000ff";
		}
		stroke(clor)
		strokeWeight(2)
		line(0, -400, 0, 0, 400, 0)
	}
	pop()
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
